fn fibonacci(n: usize) -> Vec<i32> {
    let mut fib = Vec::with_capacity(n);
    // Base cases guaranteed: n >= 2
    fib.push(0);
    fib.push(1);

    for i in 2..n {
        // Safe to unwrap because length >= 2 and i >= 2
        let next = fib[i - 1].checked_add(fib[i - 2]).expect("Overflow should not occur given constraints");
        fib.push(next);
    }
    fib
}